SELECT CASE WHEN duration_sec >= 506 THEN 'high' WHEN duration_sec >= 202 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, event_type, AVG(duration_sec) AS avg_duration_sec, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range, COUNT(CASE WHEN event_type = 'purchase' THEN 1 END) AS purchase_count FROM web_events GROUP BY duration_sec_bucket, event_type HAVING COUNT(CASE WHEN event_type = 'purchase' THEN 1 END) < 3 ORDER BY duration_sec_bucket, event_type;
